public interface Shape {
    double area();
}

public class AreaCalculator {
    private List<Shape> shapes;

    public AreaCalculator(List<Shape> shapes) {
        this.shapes = shapes;
    }

    public double sum() {
        double totalArea = 0;

        for (Shape shape : shapes) {
            totalArea += shape.area();
        }

        return totalArea;
    }
}

